import {showMemberSheet} from './member-sheet.js';
import {allCNs,queryMember,memberWorkbook,boxesForQuery} from './member-query.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>n===null||n===undefined?'—':Number(n).toFixed(2);
export function installMemberQuery({getBoxes,toast}){
  const nav=document.querySelector('nav');nav.insertAdjacentHTML('beforeend','<button id="memberQueryBtn"><span>⌕</span> 按 CN 查询</button>');
  const dialog=document.createElement('dialog');dialog.className='member-query-dialog';document.body.append(dialog);
  let boxes=[],names=[],report=null,includeArchived=false;
  const table=(head,rows)=>`<div class="mq-scroll"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
  const cells=values=>`<tr>${values.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`;
  function candidates(){const value=dialog.querySelector('#memberSearch').value;const hits=names.filter(n=>n.toLocaleLowerCase().includes(value.toLocaleLowerCase()));dialog.querySelector('#memberCandidates').innerHTML=hits.map(cn=>`<button type="button" class="quiet" data-cn="${esc(cn)}">${esc(cn)}</button>`).join('')||'<p>没有找到该 CN，请检查拼写或箱子备份。</p>';}
  function display(){const area=dialog.querySelector('#memberReport');dialog.querySelector('#memberExport').disabled=!report?.boxes.length;dialog.querySelector('#memberSheet').disabled=!report?.boxes.length;if(!report){area.innerHTML='<p class="mq-empty">选择一个 CN，查看该成员在各箱的商品和运费。</p>';return;}
    area.innerHTML=`<h3>${esc(report.cn)}</h3><div class="mq-summary">${report.boxes.length} 个箱子 · ${report.orderCount} 个订单 · ${report.qty} 件<span>${report.pending?'可结算箱运费小计':'总运费'} ¥${num(report.cents/100)}${report.pending?` · ${report.pending} 箱待结算`:''}</span></div>${report.boxes.length>1?`<h3>跨箱商品总列表</h3><p class="mq-note">按完全相同的商品名称合并数量；各笔来源和不同克重保留在下方。按人合称的商品重量请查看订单小计。</p>${table(['商品名称','总数量','所在箱数','商品重（克）'],report.combined.map(r=>cells([r.product,r.qty,r.boxCount,r.missing?'未逐件称全':num(r.net)])))}`:''}<h3>分箱明细</h3>${report.boxes.map((b,index)=>`<details class="mq-box" open><summary>${esc(b.name)}${b.archived?' · 已归档':''} <small>箱 ${index+1} · ${b.orders.length} 单 · ${b.qty} 件</small></summary><div class="mq-box-body"><p class="mq-fee">${b.shipping?`按当前数据可结算 · 运费 ¥${num(b.shipping.fee)} · 最终重量 ${num(b.shipping.g)} 克<br>商品 ${num(b.shipping.net)} 克 ＋ 订单包装 ${num(b.shipping.pack)} 克 ＋ 箱重分摊 ${num(b.shipping.box)} 克`:`待结算：${esc(b.reason)}`}</p>${table(['订单 / 来源','商品名称','数量','单件克重','商品重（克）','备注'],b.items.map(r=>`<tr><td>${esc(r.order)}<small>${esc(r.source)}</small></td><td>${esc(r.product)}</td><td>${r.qty}</td><td>${r.mode==='按人合称'?'按人合称':num(r.unit)}</td><td>${num(r.net)}</td><td>${esc(r.note)}</td></tr>`))}${b.orders.filter(o=>o.note).map(o=>`<p class="mq-order-note"><strong>${esc(o.order)} · 订单备注</strong><br>${esc(o.note)}</p>`).join('')}<h4>订单重量小计（本人部分）</h4>${table(['订单','商品重（克）','订单包装分摊（克）','含订单包装重（克）','状态'],b.orders.map(o=>cells([o.order,num(o.net),num(o.pack),num(o.d),o.status])))}</div></details>`).join('')}<p class="mq-note">“—”表示尚无可用数据。重量显示两位小数，计算保留原精度；运费沿用整箱结算的分摊结果。</p>`;
  }
  function load(){const all=getBoxes();boxes=boxesForQuery(all,includeArchived);names=allCNs(boxes);const scope=dialog.querySelector('#memberScope');if(scope)scope.textContent=`当前查询 ${boxes.length} 个箱子${includeArchived?'（包含归档）':'（不含归档）'}。全部保存 ${all.length} 箱，其中 ${all.filter(b=>b.archived).length} 箱已归档。`;}
  document.querySelector('#memberQueryBtn').onclick=()=>{try{load();report=null;dialog.innerHTML=`<div class="dialog-heading"><h2>按 CN 查询 · 跨箱查询</h2><button class="quiet" id="memberClose">关闭</button></div><p class="mq-note"><span id="memberScope"></span>先搜索，再点击完整 CN；不同名字分别统计。</p><label class="mq-archive-choice"><input type="checkbox" id="memberIncludeArchived" ${includeArchived?'checked':''}>包含归档箱子</label><div class="mq-tools"><label>成员 CN<input type="search" id="memberSearch" placeholder="输入 CN，或从下方选择" autocomplete="off"></label><button class="quiet" id="memberRefresh">刷新数据</button><button class="quiet" id="memberSheet" disabled>生成团员核对单</button><button class="primary" id="memberExport" disabled>下载 Excel</button></div><div id="memberCandidates" class="mq-candidates" aria-label="选择成员"></div><div id="memberReport" aria-live="polite"></div>`;load();candidates();display();dialog.showModal();dialog.querySelector('#memberSearch').focus();}catch(e){toast(e.message);}};
  dialog.addEventListener('change',e=>{if(e.target.id!=='memberIncludeArchived')return;try{includeArchived=e.target.checked;const cn=report?.cn;load();report=cn?queryMember(boxes,cn):null;candidates();display();}catch(e){report=null;display();toast(e.message);}});
  dialog.addEventListener('input',e=>{if(e.target.id!=='memberSearch')return;report=null;candidates();display();});
  dialog.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
    try{
      if(b.id==='memberClose')dialog.close();
      if(b.hasAttribute('data-cn')){load();report=queryMember(boxes,b.dataset.cn);dialog.querySelector('#memberSearch').value=b.dataset.cn;candidates();display();}
      if(b.id==='memberRefresh'){const cn=report?.cn;load();report=cn?queryMember(boxes,cn):null;candidates();display();toast('已读取最新保存的数据');}
      if(b.id==='memberSheet'&&report){b.disabled=true;try{load();report=queryMember(boxes,report.cn);display();await showMemberSheet(report);}finally{b.disabled=!report?.boxes.length;}}
      if(b.id==='memberExport'&&report){load();report=queryMember(boxes,report.cn);display();if(!report.boxes.length)throw Error('该成员已没有商品记录，请重新选择');if(!window.XLSX)throw Error('Excel 组件尚未加载，请稍后重试');window.XLSX.writeFile(memberWorkbook(report,window.XLSX),`${report.cn.replace(/[\\/:*?"<>|]/g,'_')}-跨箱商品与运费.xlsx`);}
    }catch(e){report=null;display();toast(e.message);}
  });
}
